-- SQLite chạy demo/kiểm thử: giữ nguyên 9 bảng và tên cột giống SQL Server.
PRAGMA foreign_keys=ON;
CREATE TABLE VaiTro (MaVaiTro INTEGER PRIMARY KEY, TenVaiTro TEXT NOT NULL UNIQUE, MoTa TEXT);
CREATE TABLE NguoiDung (MaNguoiDung INTEGER PRIMARY KEY, MaVaiTro INTEGER NOT NULL REFERENCES VaiTro, HoVaTen TEXT NOT NULL, Email TEXT NOT NULL UNIQUE, MatKhauHash TEXT NOT NULL, SoDienThoai TEXT, DiaChi TEXT, TrangThai INTEGER NOT NULL DEFAULT 1 CHECK (TrangThai IN (0,1)), NgayTao TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE DanhMuc (MaDanhMuc INTEGER PRIMARY KEY, TenDanhMuc TEXT NOT NULL UNIQUE, MoTa TEXT);
CREATE TABLE SanPham (MaSanPham INTEGER PRIMARY KEY, MaDanhMuc INTEGER NOT NULL REFERENCES DanhMuc, MaNguoiTao INTEGER REFERENCES NguoiDung, TenSanPham TEXT NOT NULL, GiaBan REAL NOT NULL CHECK(GiaBan>=0), ThuongHieu TEXT, MoTa TEXT, NgayTao TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE BienTheSanPham (MaBienThe INTEGER PRIMARY KEY, MaSanPham INTEGER NOT NULL REFERENCES SanPham ON DELETE CASCADE, KichThuoc TEXT NOT NULL, MauSac TEXT NOT NULL, SoLuongTon INTEGER NOT NULL DEFAULT 0 CHECK(SoLuongTon>=0), UNIQUE(MaSanPham,KichThuoc,MauSac));
CREATE TABLE GioHang (MaGioHang INTEGER PRIMARY KEY, MaNguoiDung INTEGER NOT NULL UNIQUE REFERENCES NguoiDung ON DELETE CASCADE, NgayTao TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ChiTietGioHang (MaChiTietGioHang INTEGER PRIMARY KEY, MaGioHang INTEGER NOT NULL REFERENCES GioHang ON DELETE CASCADE, MaBienThe INTEGER NOT NULL REFERENCES BienTheSanPham, SoLuong INTEGER NOT NULL DEFAULT 1 CHECK(SoLuong>0), UNIQUE(MaGioHang,MaBienThe));
CREATE TABLE DonHang (MaDonHang INTEGER PRIMARY KEY, MaNguoiDung INTEGER REFERENCES NguoiDung, NgayDat TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, TrangThai TEXT NOT NULL DEFAULT 'Chờ xác nhận' CHECK(TrangThai IN ('Chờ xác nhận','Đã xác nhận','Hoàn thành','Đã hủy')), TongTien REAL NOT NULL DEFAULT 0 CHECK(TongTien>=0));
CREATE TABLE ChiTietDonHang (MaChiTietDon INTEGER PRIMARY KEY, MaDonHang INTEGER NOT NULL REFERENCES DonHang ON DELETE CASCADE, MaBienThe INTEGER NOT NULL REFERENCES BienTheSanPham, SoLuong INTEGER NOT NULL CHECK(SoLuong>0), DonGia REAL NOT NULL CHECK(DonGia>=0), ThanhTien REAL GENERATED ALWAYS AS (SoLuong*DonGia) STORED, UNIQUE(MaDonHang,MaBienThe));
CREATE INDEX IX_SanPham_MaDanhMuc ON SanPham(MaDanhMuc);
CREATE INDEX IX_BienTheSanPham_MaSanPham ON BienTheSanPham(MaSanPham);
CREATE INDEX IX_DonHang_MaNguoiDung ON DonHang(MaNguoiDung);
CREATE TRIGGER trg_CTDH_ai AFTER INSERT ON ChiTietDonHang BEGIN UPDATE DonHang SET TongTien=(SELECT COALESCE(SUM(ThanhTien),0) FROM ChiTietDonHang WHERE MaDonHang=NEW.MaDonHang) WHERE MaDonHang=NEW.MaDonHang; END;
CREATE TRIGGER trg_CTDH_ad AFTER DELETE ON ChiTietDonHang BEGIN UPDATE DonHang SET TongTien=(SELECT COALESCE(SUM(ThanhTien),0) FROM ChiTietDonHang WHERE MaDonHang=OLD.MaDonHang) WHERE MaDonHang=OLD.MaDonHang; END;
CREATE TRIGGER trg_CTDH_au AFTER UPDATE ON ChiTietDonHang BEGIN UPDATE DonHang SET TongTien=(SELECT COALESCE(SUM(ThanhTien),0) FROM ChiTietDonHang WHERE MaDonHang=NEW.MaDonHang) WHERE MaDonHang=NEW.MaDonHang; UPDATE DonHang SET TongTien=(SELECT COALESCE(SUM(ThanhTien),0) FROM ChiTietDonHang WHERE MaDonHang=OLD.MaDonHang) WHERE MaDonHang=OLD.MaDonHang; END;
